// Il dato arriva nel body del webhook
const caseName = $input.item.json.body.case_name;

// Trasforma il nome in formato URL Wikipedia
const wikiUrl = `https://en.wikipedia.org/wiki/${caseName.replace(/ /g, '_')}`;

return {
  json: {
    case_name: caseName,
    wiki_url: wikiUrl
  }
};

const html = $input.item.json.data;

// Rimuove tag HTML basilari (regex semplice per MVP)
const text = html
  .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
  .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '')
  .replace(/<[^>]+>/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// Prendi primi 3000 caratteri
const summary = text.substring(0, 3000);

return {
  json: {
    case_name: $input.item.json.case_name,
    wiki_url: $input.item.json.wiki_url,
    raw_text: summary
  }
};

// Parse la risposta AI
let outline;
try {
  // Anthropic restituisce la risposta in un formato diverso
  const aiResponse = $input.item.json.text || $input.item.json.message?.content || $input.item.json.response;

  // Rimuove eventuali backtick markdown
  const cleanJson = aiResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  outline = JSON.parse(cleanJson);
} catch (error) {
  return {
    json: {
      error: "Failed to parse AI response",
      raw_ai_output: $input.item.json,
      error_message: error.message
    }
  };
}

return {
  json: {
    case_name: $('Code in JavaScript1').item.json.case_name,
    wiki_url: $('Code in JavaScript1').item.json.wiki_url,
    outline: outline,
    generated_at: new Date().toISOString()
  }
};
